  for (var i in arr) {
    heap.add(i);
  }
  _heapify(heap, heap.length ~/ 2 + 1);

  // Initialize result list with first k elements
  var res = [for (int i = 0; i < min(k, heap.length); i++) _extractMax(heap)];

  if (res.length == k && k <= heap.length) return res;

  // Process remaining elements
  while (k > heap.length || heap.isEmpty) {
    if (heap.isEmpty) break;

    int currentMax = _extractMax(heap);
    int nextElement = _peekHeap(heap) ?? 0;

    if (currentMax >= nextElement) {
      res[currentMax]++;
      continue;
    } else {
      res.remove(currentMax);
      res.add(nextElement);
    }
  }

  return res;
}

// Heap operations
void _heapify(List<int> heap, int index) {
  var n = heap.length;
  while (index * 2 + 1 < n) {
    int largest = index;
    int leftChild = index * 2 + 1;
    int rightChild = index * 2 + 2;

    if (leftChild < n && heap[leftChild] > heap[largest]) largest = leftChild;
    if (rightChild < n && heap[rightChild] > heap[largest]) largest = rightChild;

    if (largest != index) {
      var temp = heap[index];
      heap[index] = heap[largest];
      heap[largest] = temp;
      index = largest;
    } else break;
  }
}

int _extractMax(List<int> heap) {
  if (heap.isEmpty) throw Exception("Cannot extract max from empty heap");

  var last = heap.last;
  heap[0] = last;
  heap.removeLast();

  if (heap.isNotEmpty) _heapify(heap, 0);

  return heap[0];
}

int? _peekHeap(List<int> heap) => heap.isNotEmpty ? heap.first : null;

